import asyncio,sys
from h import *
async def main():
    async with Env() as e:
        pg=await e.page(w=1100,h=900)
        ok('modules loaded',await pg.evaluate("!!(MSA.study&&MSA.sched&&MSA.sched.conflicts)"))
        # ---- routine seeded as real tasks
        await pg.evaluate("MSA.go('home')"); await pg.wait_for_timeout(500)
        await pg.evaluate("MSA.state.ui.hometab='tasks';MSA.save();MSA.rerender()"); await pg.wait_for_timeout(500)
        r=await pg.evaluate("(()=>{const k=MSA.u.dateKey(new Date());const l=MSA.state.tasks.filter(x=>x.routine&&x.rday===k).sort((a,b)=>a.start<b.start?-1:1);return [l.length,l[0]&&l[0].start.slice(11),l[0]&&l[0].due.slice(11),l[6]&&l[6].title,l[6]&&l[6].start.slice(11),l[6]&&l[6].due.slice(11)]})()")
        ok('7 routine tasks for today with right times',r==[7,'17:30','18:30','نوم','23:30','23:30'],r)
        n=await pg.evaluate("MSA.state.tasks.filter(x=>x.routine).length")
        ok('routine generated for 14 days',n==98,n)
        ok('default routine has no internal clash',await pg.evaluate("MSA.sched.dayConflicts(MSA.u.dateKey(new Date())).length===0"))
        await pg.evaluate("MSA.state.ui.wk={mode:'day'};MSA.save();MSA.rerender()"); await pg.wait_for_timeout(400)
        txt=await pg.inner_text('#wkBoard')
        ok('weekly board shows routine ranges',('17:30–18:30' in txt or '17:30' in txt) and 'نوم' in txt,txt[:300])
        ok('routine not counted as overdue',await pg.evaluate("(()=>{const y=new Date(Date.now()-864e5*2),k=MSA.u.dateKey(y);const x=MSA.tasksApi.blank({title:'قديم',due:k+'T10:00',start:k+'T09:00'});x.routine='zz';x.rday=k;MSA.state.tasks.push(x);MSA.rerender();const a=document.querySelector('#wkBoard').innerText.includes('متأخرة');return !a})()"))
        # ---- conflicts
        k=await pg.evaluate("MSA.u.dateKey(new Date())")
        c=await pg.evaluate("""(k)=>{const mk=(s,d)=>({id:'zz',type:'task',title:'اجتماع',start:k+'T'+s,due:k+'T'+d,status:'todo'});
          return [MSA.sched.conflicts(mk('20:15','20:45')).map(x=>x.title),MSA.sched.conflicts(mk('18:30','18:45')).map(x=>x.title),MSA.sched.conflicts(mk('16:00','16:30')).length,MSA.sched.conflicts({id:'zz',type:'task',title:'p',due:k+'T23:59',status:'todo'}).length,MSA.sched.conflicts({id:'zz',type:'task',title:'p',due:k+'T22:00',status:'todo'}).map(x=>x.title),MSA.sched.conflicts({id:'zz',type:'task',title:'p',due:k+'T23:30',status:'todo'}).map(x=>x.title)]}""",k)
        ok('overlap with تعلم وتطبيق detected',c[0]==['تعلم وتطبيق'],c)
        ok('starting at 18:30 overlaps only the 18:30–20:00 block',c[1]==['وقت الأسرة'],c)
        ok('adjacent (ends exactly when other starts) is not a clash',c[2]==0,c)
        ok('untimed (23:59) task never clashes',c[3]==0,c)
        ok('point inside block clashes',c[4]==['ألعاب'],c)
        ok('point equal to the sleep point clashes with it only',c[5]==['نوم'],c)
        # quick add with a clashing time asks first
        await pg.fill('#wkIn','مهمة تصادم'); await pg.fill('#wkTm','20:30'); await pg.click('[data-wk=add]'); await pg.wait_for_timeout(400)
        dlg=await pg.evaluate("(document.querySelector('#overlayRoot')||document.body).innerText")
        ok('clash warning dialog shown',('تعارض' in dlg) and ('تعلم وتطبيق' in dlg),dlg[:200])
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        ok('cancel keeps task out',await pg.evaluate("!MSA.state.tasks.some(x=>x.title==='مهمة تصادم')"))
        await pg.click('[data-wk=add]'); await pg.wait_for_timeout(400)
        await pg.evaluate("(()=>{const b=[...document.querySelectorAll('#overlayRoot button')].find(b=>/احفظ برضه/.test(b.innerText));b&&b.click()})()"); await pg.wait_for_timeout(500)
        ok('"save anyway" adds it',await pg.evaluate("MSA.state.tasks.some(x=>x.title==='مهمة تصادم')"))
        txt=await pg.inner_text('#wkBoard')
        ok('banner + row flag show the clash',('تعارض' in txt),txt[:200])
        # ---- sub-tasks are opt-in
        await pg.evaluate("MSA.openTaskEditor(null,{type:'task'})"); await pg.wait_for_timeout(500)
        ok('new task: sub-tasks off by default',await pg.evaluate("(()=>{const c=document.querySelector('#tSubOn'),b=document.querySelector('#tClBox');return c&&!c.checked&&b.hidden})()"))
        await pg.fill('#tTitle','مهمة بوصف فقط'); await pg.click('.drawer .btn.primary, .dw .btn.primary, button.primary:has-text("حفظ")'); await pg.wait_for_timeout(500)
        ok('saved without sub-tasks (description-only allowed)',await pg.evaluate("(()=>{const x=MSA.state.tasks.find(t=>t.title==='مهمة بوصف فقط');return x&&x.subOn===false&&x.checklist.length===0})()"))
        await pg.evaluate("MSA.openTaskEditor(null,{type:'task'})"); await pg.wait_for_timeout(500)
        await pg.fill('#tTitle','مهمة بمهام فرعية'); await pg.click('#tSubOn'); await pg.wait_for_timeout(200)
        ok('ticking the option reveals the sub-task box',await pg.evaluate("!document.querySelector('#tClBox').hidden"))
        for s in ['فرعية 1','فرعية 2']:
            await pg.fill('#tClNew',s); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(150)
        await pg.click('button.primary:has-text("حفظ")'); await pg.wait_for_timeout(500)
        ok('sub-tasks saved + subOn true',await pg.evaluate("(()=>{const x=MSA.state.tasks.find(t=>t.title==='مهمة بمهام فرعية');window.__sx=x.id;return x.subOn===true&&x.checklist.length===2})()"))
        await pg.evaluate("(()=>{const x=MSA.state.tasks.find(t=>t.id===window.__sx);x.due=MSA.u.dateKey(new Date())+'T23:59';MSA.save();MSA.rerender()})()"); await pg.wait_for_timeout(500)
        ok('weekly row lists sub-tasks under the task',await pg.evaluate("document.querySelectorAll('.wk-t[data-id=\"'+window.__sx+'\"] .wk-subs .wk-sub-i').length===2"))
        await pg.click('.wk-t[data-id="%s"] .wk-sub-i input'%await pg.evaluate("window.__sx")); await pg.wait_for_timeout(300)
        r=await pg.evaluate("(()=>{const x=MSA.state.tasks.find(t=>t.id===window.__sx);return [x.checklist[0].done,x.status]})()")
        ok('tick a sub-task: it is done, main task stays open',r==[True,'todo'],r)
        await pg.click('.wk-t[data-id="%s"] .wk-sub-i:nth-child(2) span'%await pg.evaluate("window.__sx")); await pg.wait_for_timeout(300)
        ok('clicking the sub-task text toggles it and does not open the editor',await pg.evaluate("(()=>{const x=MSA.state.tasks.find(t=>t.id===window.__sx);return x.checklist[1].done&&!document.querySelector('#tTitle')})()"))
        # ---- routine manager
        await pg.click('[data-wk=routine]'); await pg.wait_for_timeout(400)
        ok('manager lists 7 items',await pg.evaluate("document.querySelectorAll('.rt-row').length===7"))
        await pg.evaluate("(()=>{const i=document.querySelectorAll('.rt-row [data-f=title]')[2];i.value='كورس مونتاج';i.dispatchEvent(new Event('input',{bubbles:true}));const f=document.querySelectorAll('.rt-row [data-f=from]')[3];f.value='21:00';f.dispatchEvent(new Event('input',{bubbles:true}))})()")
        w=await pg.evaluate("(()=>{const w=document.querySelector('#rtWarn');return [w.hidden,w.textContent]})()")
        ok('manager warns about overlapping items',(not w[0]) and 'كورس مونتاج' in w[1],w)
        await pg.evaluate("(()=>{const f=document.querySelectorAll('.rt-row [data-f=from]')[3];f.value='21:30';f.dispatchEvent(new Event('input',{bubbles:true}))})()")
        await pg.click('.modal button.primary:has-text("حفظ"), button.primary:has-text("حفظ")'); await pg.wait_for_timeout(500)
        r=await pg.evaluate("(()=>{const k=MSA.u.dateKey(new Date());const l=MSA.state.tasks.filter(x=>x.routine&&x.rday===k);return [l.length,l.some(x=>x.title==='كورس مونتاج')]})()")
        ok('routine edit applies to today\'s task (no duplicates)',r==[7,True],r)
        # ---- Learning: videos
        await pg.evaluate("(()=>{const L=MSA.state.learning;L.videos.push({id:'vt1',folder:null,url:'https://example.com/v1',title:'درس الإضاءة',note:'',created:Date.now()});MSA.state.ui.ltab='videos';MSA.state.ui.learnFolder=null;MSA.save();MSA.go('learn')})()"); await pg.wait_for_timeout(700)
        card='.vcard[data-id="vt1"]'
        ok('card has notes, done and fav icons',await pg.evaluate("(()=>{const c=document.querySelector('%s');return !!(c.querySelector('.note-btn')&&c.querySelector('.done-btn')&&c.querySelector('.fav-btn'))})()"%card))
        await pg.click(card+' .done-btn'); await pg.wait_for_timeout(300)
        ok('done check marks the video + badge',await pg.evaluate("(()=>{const v=MSA.state.learning.videos.find(v=>v.id==='vt1');return v.done===true&&!!v.doneAt&&!!document.querySelector('%s .pill.ok')})()"%card))
        await pg.click(card+' .note-btn'); await pg.wait_for_timeout(400)
        await pg.fill('#stNote','ملاحظة تجريبية'); await pg.click('#stOk'); await pg.wait_for_timeout(500)
        ok('note saved from the card icon',await pg.evaluate("MSA.state.learning.videos.find(v=>v.id==='vt1').note==='ملاحظة تجريبية'"))
        ok('note icon lit when a note exists',await pg.evaluate("document.querySelector('%s .note-btn').classList.contains('on')"%card))
        await pg.evaluate("document.querySelectorAll('#toastRoot .toast').forEach(t=>t.remove())")
        await pg.click(card+' .vthumb'); await pg.wait_for_timeout(500)
        tt=await pg.evaluate("document.querySelector('#toastRoot').innerText")
        ok('re-opening a finished video says it was studied before',('تم دراسة هذا (فيديو) من قبل' in tt) and 'درس الإضاءة' in tt,tt)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        await pg.click(card+' .done-btn'); await pg.wait_for_timeout(300)
        await pg.evaluate("document.querySelectorAll('#toastRoot .toast').forEach(t=>t.remove())")
        await pg.click(card+' .vthumb'); await pg.wait_for_timeout(500)
        ok('un-finished video: no studied-before message','من قبل' not in await pg.evaluate("document.querySelector('#toastRoot').innerText"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        await pg.click(card+' .fav-btn'); await pg.wait_for_timeout(300)
        ok('existing favourite star still works',await pg.evaluate("MSA.state.learning.videos.find(v=>v.id==='vt1').fav===true"))
        # ---- References
        await pg.evaluate("(()=>{MSA.state.refs.push({id:'rt1',folder:null,url:'https://example.com/ref',title:'مرجع ألوان',tags:[],created:Date.now()});MSA.state.ui.ltab='refs';MSA.state.ui.refFolder=null;MSA.save();MSA.go('learn')})()"); await pg.wait_for_timeout(700)
        rc='.ref[data-id="rt1"]'
        ok('ref card has notes, done and fav icons',await pg.evaluate("(()=>{const c=document.querySelector('%s');return !!(c&&c.querySelector('.note-btn')&&c.querySelector('.done-btn')&&c.querySelector('.fav-btn'))})()"%rc))
        ok('add file / audio / video button exists',await pg.evaluate("!!document.querySelector('[data-act=file]')"))
        await pg.click(rc+' .done-btn'); await pg.wait_for_timeout(300)
        await pg.evaluate("window.open=()=>null;MSA.openLink=()=>{};document.querySelectorAll('#toastRoot .toast').forEach(t=>t.remove())")
        await pg.click(rc+' .ref-link'); await pg.wait_for_timeout(400)
        tt=await pg.evaluate("document.querySelector('#toastRoot').innerText")
        ok('opening a finished reference says it was studied before',('تم دراسة هذا (رابط) من قبل' in tt) and 'مرجع ألوان' in tt,tt)
        await pg.click(rc+' .note-btn'); await pg.wait_for_timeout(400); await pg.fill('#stNote','نوت مرجع'); await pg.click('#stOk'); await pg.wait_for_timeout(500)
        ok('reference note saved',await pg.evaluate("MSA.state.refs.find(r=>r.id==='rt1').note==='نوت مرجع'"))
        # file kind picker
        await pg.click('[data-act=file]'); await pg.wait_for_timeout(400)
        ok('file picker offers document/audio/video',await pg.evaluate("document.querySelectorAll('[data-k]').length===3"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        # deterministic ids + off/on
        ok('routine task ids are unique and deterministic',await pg.evaluate("(()=>{const ids=MSA.state.tasks.filter(x=>x.routine).map(x=>x.id);return new Set(ids).size===ids.length&&ids.every(i=>i.startsWith('rt_'))})()"))
        await pg.evaluate("MSA.state.ui.hometab='tasks';MSA.go('home')"); await pg.wait_for_timeout(600)
        await pg.click('[data-wk=routine]'); await pg.wait_for_timeout(400)
        await pg.click('button:has-text("إيقاف الروتين")'); await pg.wait_for_timeout(400)
        await pg.evaluate("(()=>{const b=[...document.querySelectorAll('#overlayRoot button')].find(b=>b.classList.contains('danger')||/تأكيد|موافق|OK|حذف/.test(b.innerText));b&&b.click()})()"); await pg.wait_for_timeout(500)
        ok('turning the routine off removes unfinished routine tasks',await pg.evaluate("MSA.state.routine.off===true&&MSA.state.tasks.filter(x=>x.routine&&x.status!=='done').length===0"))
        await pg.evaluate("MSA.sched.ensure()")
        ok('stays off (no regeneration)',await pg.evaluate("MSA.state.tasks.filter(x=>x.routine).length<=0||MSA.state.tasks.filter(x=>x.routine&&x.status!=='done').length===0"))
        await pg.click('[data-wk=routine]'); await pg.wait_for_timeout(400); await pg.click('button:has-text("تشغيل الروتين")'); await pg.wait_for_timeout(500)
        ok('turning it on regenerates the schedule',await pg.evaluate("MSA.state.routine.off===false&&MSA.state.tasks.filter(x=>x.routine).length>=90"))
        # English UI
        await pg.evaluate("MSA.state.settings.lang='en';MSA.save();MSA.rerender()"); await pg.wait_for_timeout(500)
        ok('no page errors',not pg.errs,pg.errs)
    return summary()
sys.exit(asyncio.run(main()))
